input.command:
mkdir -p /tmp/pwtool/shots && cat > /tmp/pwtool/shot.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch({ args: ['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--ignore-gpu-blocklist'] });
  const p = await b.newPage({ viewport: { width: 1280, height: 720 } });
  const errs = []; p.on('console', m => { if (m.type()==='error'||m.type()==='warning') errs.push(m.text()); }); p.on('pageerror', e => errs.push(String(e)));
  const ts = (process.argv[2]||'0,2,4,5,5.8,6.05,6.4,7,8,9.2,9.99').split(',');
  for (const t of ts) {
    await p.goto('file://<workspace>/.ambition/direct/index.html?t=' + t);
    await p.waitForFunction(() => window.__ready, null, { timeout: 60000 });
    await p.waitForTimeout(2500);
    await p.screenshot({ path: `/tmp/pwtool/shots/t${t}.png` });
  }
  console.log(errs.slice(0,10).join('\n') || 'no errors');
  await b.close();
})();
EOF
cd /tmp/pwtool && node shot.js

