input.command:
cd <workspace>/.ambition/direct && python3 - <<'EOF'
s=open('index.html').read()
a="const dist = 74 - 30 * env;"
b="const dist = (74 - 30 * env) * Math.pow(Math.max(1, 1.5 / camera.aspect), 0.85); // keep the system framed on portrait screens"
assert a in s; s=s.replace(a,b); open('index.html','w').write(s)
EOF
cat > /tmp/pwtool/mobile.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch({ args: ['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'] });
  const p = await b.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
  for (const t of ['1','7.3']) {
    await p.goto('file://<workspace>/.ambition/direct/index.html?t=' + t);
    await p.waitForFunction(() => window.__ready); await p.waitForTimeout(3000);
    await p.screenshot({ path: `<workspace>/.ambition/direct/shots/mobile_t${t}.png` });
  }
  // live playback sanity: time advances without ?t
  await p.goto('file://<workspace>/.ambition/direct/index.html'); await p.waitForTimeout(4000);
  await p.screenshot({ path: '<workspace>/.ambition/direct/shots/mobile_live.png' });
  await b.close();
})();
EOF
cd /tmp/pwtool && node mobile.js

